/**
 * The two published SHA-1 collisions, as far as the bytes that collide.
 *
 * From the test data of https://github.com/cr-marcstevens/sha1collisiondetection
 * (`test/shattered-{1,2}.pdf`, `test/sha-mbles-{1,2}.bin`):
 *
 * - SHAttered (Stevens, Bursztein, Karpman, Albertini, Markov, 2017): two PDFs
 *   with one SHA-1. They differ only in bytes 192 to 319 (two blocks), and
 *   everything after is the same in both, so the first 320 bytes of each are
 *   the whole collision. Here: those 320 bytes.
 * - Shambles (Leurent, Peyrin, 2020): the first chosen-prefix collision, two
 *   640-byte messages with different beginnings and one SHA-1. Here: whole.
 *
 * Hex in a source file rather than binary fixtures, so that this repository
 * holds no file whose own bytes are the colliding blocks.
 */
const join = (lines: readonly string[]): Uint8Array => {
  const hex = lines.join("");
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
};

